CREATE TABLE estoque_item(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant(id),versao bigint NOT NULL DEFAULT 0,nome varchar(160) NOT NULL,codigo varchar(60) NOT NULL,tipo varchar(20) NOT NULL CHECK(tipo IN ('CONSUMIVEL','PATRIMONIO')),unidade varchar(30) NOT NULL,local varchar(200),responsavel_usuario_id uuid,ativo boolean NOT NULL DEFAULT true,atualizado_em timestamptz NOT NULL DEFAULT now(), saldo numeric(12,3) NOT NULL DEFAULT 0 CHECK(saldo>=0),UNIQUE(tenant_id,id),UNIQUE(tenant_id,codigo),FOREIGN KEY(tenant_id,responsavel_usuario_id) REFERENCES usuario_tenant(tenant_id,usuario_id) ON DELETE SET NULL (responsavel_usuario_id));
CREATE INDEX estoque_item_lista ON estoque_item(tenant_id,lower(nome),id);
CREATE TABLE estoque_movimento(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant(id),item_id uuid NOT NULL,chave uuid NOT NULL,tipo varchar(20) NOT NULL CHECK(tipo IN ('ENTRADA','SAIDA','AJUSTE')),quantidade numeric(12,3) NOT NULL CHECK(quantidade>=0),saldo_antes numeric(12,3) NOT NULL CHECK(saldo_antes>=0),saldo_depois numeric(12,3) NOT NULL CHECK(saldo_depois>=0),motivo varchar(500) NOT NULL,responsavel_usuario_id uuid,registrado_por uuid REFERENCES usuario(id) ON DELETE SET NULL,registrado_em timestamptz NOT NULL,UNIQUE(tenant_id,item_id,chave),FOREIGN KEY(tenant_id,item_id) REFERENCES estoque_item(tenant_id,id),FOREIGN KEY(tenant_id,responsavel_usuario_id) REFERENCES usuario_tenant(tenant_id,usuario_id) ON DELETE SET NULL (responsavel_usuario_id),CHECK((tipo='ENTRADA' AND quantidade>0 AND saldo_depois=saldo_antes+quantidade) OR (tipo='SAIDA' AND quantidade>0 AND saldo_depois=saldo_antes-quantidade) OR (tipo='AJUSTE' AND saldo_depois=quantidade)));
CREATE INDEX estoque_movimento_historico ON estoque_movimento(tenant_id,item_id,registrado_em DESC,id DESC);
ALTER TABLE estoque_item ENABLE ROW LEVEL SECURITY;
ALTER TABLE estoque_movimento ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON estoque_item,estoque_movimento FROM anon,authenticated;
